import { pesoCobrable, calcularFlete } from './flete.mjs';

// `db` es cualquier objeto con query(sql, params): en producción, una conexión a Postgres.
export async function registrarEnvio(db, { id, zona, pesoKg, medidas }) {
  const kg = pesoCobrable(pesoKg, ...medidas);
  const costo = calcularFlete(zona, kg);
  await db.query('insert into envios (id, zona, kg, costo) values ($1, $2, $3, $4)', [id, zona, kg, costo]);
  return { id, zona, kg, costo };
}

export async function envioPorId(db, id) {
  const r = await db.query('select id, zona, kg::float8 as kg, costo from envios where id = $1', [id]);
  return r.rows[0] ?? null;
}

export async function totalesPorZona(db) {
  const r = await db.query(
    'select zona, count(*)::int as envios, sum(costo)::int as total from envios group by zona order by zona');
  return r.rows;
}

