import { test, before, after, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import pg from 'pg';
import { registrarEnvio, envioPorId, totalesPorZona } from './repo.mjs';

const BASE = 'prueba_envios';
const conf = { host: process.env.PGHOST, port: Number(process.env.PGPORT), user: 'postgres' };
let pool, cliente;

before(async () => {
  // Una base de verdad, creada de cero para esta corrida
  const admin = new pg.Client({ ...conf, database: 'postgres' });
  await admin.connect();
  await admin.query(`drop database if exists ${BASE}`);
  await admin.query(`create database ${BASE}`);
  await admin.end();
  pool = new pg.Pool({ ...conf, database: BASE, max: 1 });
  await pool.query(readFileSync(process.env.ESQUEMA ?? 'esquema.sql', 'utf8'));
});
after(async () => { await pool.end(); });

// Cada prueba trabaja dentro de una transacción que se deshace: no deja rastros para la siguiente.
beforeEach(async () => { cliente = await pool.connect(); await cliente.query('begin'); });
afterEach(async () => { await cliente.query('rollback'); cliente.release(); });

test('un envío guardado se lee igual que como se guardó', async () => {
  await registrarEnvio(cliente, { id: 'A-1', zona: 'GBA', pesoKg: 3.1, medidas: [10, 10, 10] });
  const leido = await envioPorId(cliente, 'A-1');
  assert.deepEqual(leido, { id: 'A-1', zona: 'GBA', kg: 3.5, costo: 5425 });
});

test('la base rechaza dos envíos con el mismo id', async () => {
  await registrarEnvio(cliente, { id: 'A-2', zona: 'CABA', pesoKg: 2, medidas: [10, 10, 10] });
  await assert.rejects(
    registrarEnvio(cliente, { id: 'A-2', zona: 'CABA', pesoKg: 2, medidas: [10, 10, 10] }),
    (e) => e.code === '23505'); // unique_violation
});

test('totalesPorZona suma por zona y deja afuera las zonas sin envíos', async () => {
  await registrarEnvio(cliente, { id: 'B-1', zona: 'CABA', pesoKg: 2, medidas: [10, 10, 10] });
  await registrarEnvio(cliente, { id: 'B-2', zona: 'CABA', pesoKg: 4, medidas: [10, 10, 10] });
  await registrarEnvio(cliente, { id: 'B-3', zona: 'INTERIOR', pesoKg: 1, medidas: [10, 10, 10] });
  const t = await totalesPorZona(cliente);
  assert.deepEqual(t, [
    { zona: 'CABA', envios: 2, total: (2500 + 400 * 2) + (2500 + 400 * 4) },
    { zona: 'INTERIOR', envios: 1, total: 6000 + 900 * 1 },
  ]);
});

