import { descuentoPorVolumen } from './descuento.mjs';

test('menos de 10 cajas no tienen descuento', () => {
  assert.equal(descuentoPorVolumen(5), 0);
});

test('desde 10 cajas hay 5 % de descuento', () => {
  assert.equal(descuentoPorVolumen(10), 0.05);
});

test('desde 50 cajas hay 10 % de descuento', () => {
  assert.equal(descuentoPorVolumen(50), 0.10);
});

test('desde 100 cajas hay 15 % de descuento', () => {
  assert.equal(descuentoPorVolumen(100), 0.15);
});

test('una cantidad negativa o con decimales es un error', () => {
  assert.throws(() => descuentoPorVolumen(-1), RangeError);
  assert.throws(() => descuentoPorVolumen(2.5), RangeError);
});

const ESCALONES = [ // de mayor a menor: el primero que alcanza gana
  { desde: 100, descuento: 0.15 },
  { desde: 50, descuento: 0.10 },
  { desde: 10, descuento: 0.05 },
];

export function descuentoPorVolumen(cajas) {
  if (!Number.isInteger(cajas) || cajas < 0) throw new RangeError('cajas inválidas');
  return ESCALONES.find((e) => cajas >= e.desde)?.descuento ?? 0;
}

