// El contrato: lo que la app (consumidora) necesita de la respuesta del servidor (proveedor).
export const CONTRATO_COTIZACION = { kg: 'number', costo: 'number' };

// Devuelve la lista de incumplimientos (vacía = cumple).
export function incumplimientos(respuesta, contrato) {
  return Object.entries(contrato)
    .filter(([campo, tipo]) => typeof respuesta[campo] !== tipo)
    .map(([campo, tipo]) => `${campo}: esperaba ${tipo}, llegó ${typeof respuesta[campo]}`);
}

