import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { CONTRATO_COTIZACION, incumplimientos } from './contrato.mjs';
import { crearServidor } from './servidor.mjs';

let servidor, base;
before(async () => {
  servidor = crearServidor();
  await new Promise((ok) => servidor.listen(0, '127.0.0.1', ok));
  base = 'http://127.0.0.1:' + servidor.address().port;
});
after(() => servidor.close());

// Lado del proveedor: el servidor real cumple lo que la app necesita.
test('contrato: la respuesta de /api/flete trae kg y costo como números', async () => {
  const r = await fetch(base + '/api/flete?zona=GBA&peso=4&l=10&a=10&h=10');
  assert.deepEqual(incumplimientos(await r.json(), CONTRATO_COTIZACION), []);
});

// Lado del consumidor: la app, con una respuesta de ejemplo del mismo contrato, la sabe leer.
test('contrato: una respuesta que cambió costo a texto se detecta', () => {
  assert.deepEqual(
    incumplimientos({ kg: 4, costo: '5700' }, CONTRATO_COTIZACION),
    ['costo: esperaba number, llegó string']);
});
